  (md5('course-question:react-native-basics:1:4')::uuid, md5('course-quiz:react-native-basics:1')::uuid, 4, 'According to the React Native documentation, what is the web analog of the `<Text>` Core Component?', 'The Core Components table lists `<p>` as the web analog for the `<Text>` component, which displays, styles, and nests strings of text.', 'https://reactnative.dev/docs/0.88/intro-react-native-components'),
  (md5('course-question:react-native-basics:1:5')::uuid, md5('course-quiz:react-native-basics:1')::uuid, 5, 'What does React Native call components that are backed by platform-specific views on Android and iOS?', 'React Native refers to platform-backed components that invoke native Android and iOS views via JavaScript as Native Components.', 'https://reactnative.dev/docs/0.88/intro-react-native-components'),
  (md5('course-question:react-native-basics:1:6')::uuid, md5('course-quiz:react-native-basics:1')::uuid, 6, 'Which release of Node.js is required by Expo when setting up your development machine?', 'The Expo system requirements specify Node.js (LTS) for setting up your development environment.', 'https://docs.expo.dev/get-started/create-a-project'),
  (md5('course-question:react-native-basics:1:7')::uuid, md5('course-quiz:react-native-basics:1')::uuid, 7, 'Which of the following operating system environments is supported by Expo for development?', 'The Expo documentation explicitly lists macOS, Windows (PowerShell and WSL 2), and Linux as supported operating systems.', 'https://docs.expo.dev/get-started/create-a-project'),
  (md5('course-question:react-native-basics:1:8')::uuid, md5('course-quiz:react-native-basics:1')::uuid, 8, 'Which command creates a default Expo project specifically targeting SDK 58?', 'The Expo documentation recommends running `npx create-expo-app@latest --template default@sdk-58` to initialise an SDK 58 project.', 'https://docs.expo.dev/get-started/create-a-project'),
  (md5('course-question:react-native-basics:1:9')::uuid, md5('course-quiz:react-native-basics:1')::uuid, 9, 'Which flag can you pass to `create-expo-app` to browse or start from an interactive list of example projects?', 'Passing the `--example` option with no name to `create-expo-app` allows you to browse the full list of official example projects interactively.', 'https://docs.expo.dev/get-started/create-a-project'),
  (md5('course-question:react-native-basics:1:10')::uuid, md5('course-quiz:react-native-basics:1')::uuid, 10, 'How does the Expo documentation describe Expo Go compared to a development build?', 'Expo documentation defines Expo Go as a playground for students and learners to try Expo quickly, whereas a development build is a custom build of your own app.', 'https://docs.expo.dev/get-started/set-up-your-environment'),
  (md5('course-question:react-native-basics:1:11')::uuid, md5('course-quiz:react-native-basics:1')::uuid, 11, 'Which command starts the local development server in an Expo project?', 'Running `npx expo start` launches the local development server and prints an interactive QR code to the terminal.', 'https://docs.expo.dev/get-started/start-developing'),
  (md5('course-question:react-native-basics:1:12')::uuid, md5('course-quiz:react-native-basics:1')::uuid, 12, 'What account requirement must be met to open a project using Expo Go on a physical iOS device?', 'When using Expo Go on a physical iOS handset, Expo Go only opens the project when Expo CLI on your computer and Expo Go on your device share the same Expo account.', 'https://docs.expo.dev/get-started/start-developing'),
  (md5('course-question:react-native-basics:1:13')::uuid, md5('course-quiz:react-native-basics:1')::uuid, 13, 'If restrictive router configurations on a network prevent your device from connecting to the server, which flag can you provide to `npx expo start`?', 'Running `npx expo start --tunnel` sets up an external tunnel connection, working around local network blocks at the cost of slower reload speeds.', 'https://docs.expo.dev/get-started/start-developing'),
  (md5('course-question:react-native-basics:1:14')::uuid, md5('course-quiz:react-native-basics:1')::uuid, 14, 'How can you reveal the in-app developer menu on a physical mobile device running your app?', 'Shaking the physical device reveals the in-app developer menu, where you can toggle Fast Refresh or reload the project.', 'https://docs.expo.dev/get-started/start-developing'),
  (md5('course-question:react-native-basics:1:15')::uuid, md5('course-quiz:react-native-basics:1')::uuid, 15, 'When running a React Native Android app over USB with adb, which command connects the device port to your development server?', 'The React Native documentation instructs running `adb -s <device name> reverse tcp:8081 tcp:8081` to forward connections from the device to your computer''s server.', 'https://reactnative.dev/docs/0.88/running-on-device')
on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, reference_url = excluded.reference_url;
update public.quiz_answers set is_correct = false where question_id in (select id from public.quiz_questions where quiz_id = md5('course-quiz:react-native-basics:1')::uuid);
