-- Quiz react-native-basics/2: Components and styling quiz (15 questions)
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('course-quiz:react-native-basics:2')::uuid, md5('chapter:react-native-basics:2')::uuid, 'Components and styling quiz', 1, false)
on conflict (id) do update set title = excluded.title, is_preview = excluded.is_preview;
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('course-question:react-native-basics:2:1')::uuid, md5('course-quiz:react-native-basics:2')::uuid, 1, 'What happens if you place a raw text string directly inside a `<View>` component without wrapping it in a `<Text>` component?', 'In React Native, you cannot place a text node directly under a `<View>`. All text nodes must be wrapped inside a `<Text>` component, otherwise an exception is raised.', 'https://reactnative.dev/docs/0.88/text'),
  (md5('course-question:react-native-basics:2:2')::uuid, md5('course-quiz:react-native-basics:2')::uuid, 2, 'When displaying a network image using `<Image source={{uri: ''https://example.com/logo.png''}} />`, which styling rule is required?', 'Unlike static resources loaded with `require`, remote network images do not have dimensions known before download, so you must manually specify the `width` and `height` in the style.', 'https://reactnative.dev/docs/0.88/images'),
  (md5('course-question:react-native-basics:2:3')::uuid, md5('course-quiz:react-native-basics:2')::uuid, 3, 'How does layout behaviour differ inside a `<Text>` component compared to a `<View>` component?', 'The `<Text>` component does not use flexbox layout for its children; instead, it uses text layout. Elements inside `<Text>` flow inline and wrap when they reach the end of the line.', 'https://reactnative.dev/docs/0.88/text'),
  (md5('course-question:react-native-basics:2:4')::uuid, md5('course-quiz:react-native-basics:2')::uuid, 4, 'How does React Native determine which static image asset to display when you provide `@2x` and `@3x` file suffixes?', 'Metro resolves static image filenames and bundles the image corresponding to the device''s screen density, choosing the closest best option if an exact match is missing.', 'https://reactnative.dev/docs/0.88/images'),
  (md5('course-question:react-native-basics:2:5')::uuid, md5('course-quiz:react-native-basics:2')::uuid, 5, 'When passing an array of style objects to a component''s `style` prop, how are conflicting properties resolved?', 'When passing an array of styles to the `style` prop, the last style in the array has precedence, allowing styles to be overridden selectively.', 'https://reactnative.dev/docs/0.88/style'),
  (md5('course-question:react-native-basics:2:6')::uuid, md5('course-quiz:react-native-basics:2')::uuid, 6, 'Which of the following is a default Flexbox behaviour in React Native that differs from web CSS?', 'In React Native, `flexDirection` defaults to `column` rather than `row`. Additionally, `alignContent` defaults to `flex-start` and `flexShrink` defaults to `0`.', 'https://reactnative.dev/docs/0.88/flexbox'),
  (md5('course-question:react-native-basics:2:7')::uuid, md5('course-quiz:react-native-basics:2')::uuid, 7, 'Suppose a container has `flex: 1` and contains three sibling views with `flex: 1`, `flex: 2`, and `flex: 3`. What proportion of available space does the second view receive along the main axis?', 'The total sum of flex values is 1 + 2 + 3 = 6. The second view has `flex: 2`, so it receives 2/6 (or 1/3) of the available space along the main axis.', 'https://reactnative.dev/docs/0.88/flexbox'),
  (md5('course-question:react-native-basics:2:8')::uuid, md5('course-quiz:react-native-basics:2')::uuid, 8, 'What happens if child components have `flex: 1` but their parent `View` has no defined `width`, `height`, or `flex` property?', 'A component can only expand to fill available space if its parent has dimensions greater than 0. Without fixed dimensions or flex on the parent, its size is 0 and flex children are not visible.', 'https://reactnative.dev/docs/0.88/height-and-width'),
  (md5('course-question:react-native-basics:2:9')::uuid, md5('course-quiz:react-native-basics:2')::uuid, 9, 'Why is `FlatList` generally preferred over `ScrollView` for rendering long or changing lists of items?', 'Unlike `ScrollView`, which renders all elements at once regardless of whether they are on screen, `FlatList` only renders elements currently visible in the viewport to maintain performance.', 'https://reactnative.dev/docs/0.88/using-a-listview'),
  (md5('course-question:react-native-basics:2:10')::uuid, md5('course-quiz:react-native-basics:2')::uuid, 10, 'Which two props are required on a `FlatList` component to render basic list data?', 'The `FlatList` component requires `data` (the source array of items) and `renderItem` (a callback function that formats and returns a component for each item).', 'https://reactnative.dev/docs/0.88/using-a-listview'),
  (md5('course-question:react-native-basics:2:11')::uuid, md5('course-quiz:react-native-basics:2')::uuid, 11, 'Why would you pass an `extraData` prop to a `FlatList`?', 'Because `FlatList` is a `PureComponent`, it only re-renders when its props change shallowly. Passing external state dependencies into `extraData` ensures the list updates when that external state changes.', 'https://reactnative.dev/docs/0.88/flatlist'),
  (md5('course-question:react-native-basics:2:12')::uuid, md5('course-quiz:react-native-basics:2')::uuid, 12, 'In a `SectionList`, what prop must each section object contain to supply its items?', 'Each section object in the `sections` array of a `SectionList` must contain its own `data` array containing the items belonging to that section.', 'https://reactnative.dev/docs/0.88/using-a-listview'),
  (md5('course-question:react-native-basics:2:13')::uuid, md5('course-quiz:react-native-basics:2')::uuid, 13, 'How does the standard `Button` component visually render on iOS compared to Android?', 'The basic `Button` renders as coloured text on iOS and as a rounded rectangle with light text on Android, matching native platform conventions.', 'https://reactnative.dev/docs/0.88/handling-touches'),
  (md5('course-question:react-native-basics:2:14')::uuid, md5('course-quiz:react-native-basics:2')::uuid, 14, 'What visual feedback does `TouchableOpacity` provide when a user presses down on it?', 'The `TouchableOpacity` component provides feedback by reducing the opacity of the button, allowing the background to show through while pressed down.', 'https://reactnative.dev/docs/0.88/handling-touches'),
  (md5('course-question:react-native-basics:2:15')::uuid, md5('course-quiz:react-native-basics:2')::uuid, 15, 'When using `Pressable`, in what order do touch callbacks fire during a standard quick tap?', 'When a user taps an element wrapped by `Pressable`, `onPressIn` is called first when the touch engages, followed by `onPressOut` when released, and finally `onPress`.', 'https://reactnative.dev/docs/0.88/pressable')
on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, reference_url = excluded.reference_url;
update public.quiz_answers set is_correct = false where question_id in (select id from public.quiz_questions where quiz_id = md5('course-quiz:react-native-basics:2')::uuid);
