  (md5('course-answer:react-native-basics:2:2:4')::uuid, md5('course-question:react-native-basics:2:2')::uuid, 4, 'You must wrap the image in a `View` with `flex: 1`.', false),
  (md5('course-answer:react-native-basics:2:3:1')::uuid, md5('course-question:react-native-basics:2:3')::uuid, 1, 'Children inside `<Text>` use text layout and wrap inline, rather than using flexbox layout.', true),
  (md5('course-answer:react-native-basics:2:3:2')::uuid, md5('course-question:react-native-basics:2:3')::uuid, 2, 'Children inside `<Text>` automatically form separate rectangular blocks stacked vertically.', false),
