-- Quiz react-native-basics/3: Navigation and data quiz (15 questions)
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('course-quiz:react-native-basics:3')::uuid, md5('chapter:react-native-basics:3')::uuid, 'Navigation and data quiz', 1, false)
on conflict (id) do update set title = excluded.title, is_preview = excluded.is_preview;
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('course-question:react-native-basics:3:1')::uuid, md5('course-quiz:react-native-basics:3')::uuid, 1, 'Where must screen routes be placed when using Expo Router?', 'All navigation routes in Expo Router are defined by the files and sub-directories inside the src/app directory. Files outside this folder cannot be navigation targets.', 'https://docs.expo.dev/router/basics/core-concepts'),
  (md5('course-question:react-native-basics:3:2')::uuid, md5('course-quiz:react-native-basics:3')::uuid, 2, 'What does a directory name enclosed in parentheses, such as `src/app/(tabs)`, represent?', 'Parentheses denote a route group. These directories allow you to organise routes and apply shared layouts without adding a segment to the URL path.', 'https://docs.expo.dev/router/basics/notation'),
  (md5('course-question:react-native-basics:3:3')::uuid, md5('course-quiz:react-native-basics:3')::uuid, 3, 'Which file serves as the initial route matching the root URL (`/`) in Expo Router?', 'Expo Router looks for the first index.tsx file matching the `/` URL, which in standard project layouts is src/app/index.tsx.', 'https://docs.expo.dev/router/basics/core-concepts'),
  (md5('course-question:react-native-basics:3:4')::uuid, md5('course-quiz:react-native-basics:3')::uuid, 4, 'What is the primary role of the root `src/app/_layout.tsx` file in an Expo Router application?', 'The root _layout.tsx file replaces App.jsx, rendering before any other route and housing global initialisation code such as font loading, splash screen handling, and navigators.', 'https://docs.expo.dev/router/basics/navigation-layouts'),
  (md5('course-question:react-native-basics:3:5')::uuid, md5('course-quiz:react-native-basics:3')::uuid, 5, 'Which component can you render in a layout file to show child routes without adding a navigator stack or tab bar?', 'The Slot component acts as a placeholder for child routes inside a layout when you want to wrap screens in elements like headers without introducing a navigator.', 'https://docs.expo.dev/router/basics/navigation-layouts'),
  (md5('course-question:react-native-basics:3:6')::uuid, md5('course-quiz:react-native-basics:3')::uuid, 6, 'How do you define a dynamic route segment in the Expo Router file tree?', 'Square brackets signify dynamic route segments in Expo Router. The enclosed name denotes the parameter extracted from that segment of the URL.', 'https://docs.expo.dev/router/basics/notation'),
  (md5('course-question:react-native-basics:3:7')::uuid, md5('course-quiz:react-native-basics:3')::uuid, 7, 'Which hook retrieves route and query parameters on the destination screen in Expo Router?', 'The useLocalSearchParams hook extracts both dynamic route variables and query parameters that were passed to the screen.', 'https://docs.expo.dev/router/basics/navigation'),
  (md5('course-question:react-native-basics:3:8')::uuid, md5('course-quiz:react-native-basics:3')::uuid, 8, 'How can you pass parameters using an object in Expo Router''s `Link` component?', 'The Link component accepts an object for its href prop containing the target pathname alongside a params object with key-value pairs.', 'https://docs.expo.dev/router/basics/navigation'),
  (md5('course-question:react-native-basics:3:9')::uuid, md5('course-quiz:react-native-basics:3')::uuid, 9, 'Which method updates query parameters on the active screen imperatively without navigating away?', 'Expo Router provides router.setParams to update query parameters on the current route without performing a transition to a new screen.', 'https://docs.expo.dev/router/basics/navigation'),
  (md5('course-question:react-native-basics:3:10')::uuid, md5('course-quiz:react-native-basics:3')::uuid, 10, 'When passing props to custom child components in React, what is the default value of a prop if it is omitted and has no fallback defined?', 'In JavaScript and React, missing component props evaluate to undefined unless a default parameter value has been defined in the component signature.', 'https://react.dev/learn/passing-props-to-a-component'),
  (md5('course-question:react-native-basics:3:11')::uuid, md5('course-quiz:react-native-basics:3')::uuid, 11, 'What does React Native''s built-in `fetch` function return when initiated?', 'The fetch method returns a JavaScript Promise that resolves to the response of the asynchronous networking operation.', 'https://reactnative.dev/docs/0.88/network'),
  (md5('course-question:react-native-basics:3:12')::uuid, md5('course-quiz:react-native-basics:3')::uuid, 12, 'Why should network calls made with `fetch` and `.json()` always include error handling such as a `try...catch` block?', 'React Native documentation notes that any errors thrown by fetch will be dropped silently unless explicitly caught with a catch handler or try...catch block.', 'https://reactnative.dev/docs/0.88/network'),
  (md5('course-question:react-native-basics:3:13')::uuid, md5('course-quiz:react-native-basics:3')::uuid, 13, 'How do you specify a POST request with a JSON payload using `fetch`?', 'To send a POST request with fetch, pass an options object as the second argument containing method: ''POST'' and a body property holding the JSON.stringify payload.', 'https://reactnative.dev/docs/0.88/network'),
  (md5('course-question:react-native-basics:3:14')::uuid, md5('course-quiz:react-native-basics:3')::uuid, 14, 'What network security restriction applies by default on iOS in React Native applications?', 'iOS enforces App Transport Security (ATS) by default, requiring network connections to use HTTPS rather than insecure cleartext HTTP.', 'https://reactnative.dev/docs/0.88/network'),
  (md5('course-question:react-native-basics:3:15')::uuid, md5('course-quiz:react-native-basics:3')::uuid, 15, 'On Android (API level 28 and above), how is cleartext HTTP traffic treated by default in React Native?', 'As of Android API level 28, cleartext traffic is blocked by default and requires setting android:usesCleartextTraffic in the manifest to allow insecure connections.', 'https://reactnative.dev/docs/0.88/network')
on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, reference_url = excluded.reference_url;
update public.quiz_answers set is_correct = false where question_id in (select id from public.quiz_questions where quiz_id = md5('course-quiz:react-native-basics:3')::uuid);
