  (md5('course-answer:react-native-basics:3:11:2')::uuid, md5('course-question:react-native-basics:3:11')::uuid, 2, 'A parsed JSON object representing the endpoint payload', false),
  (md5('course-answer:react-native-basics:3:11:3')::uuid, md5('course-question:react-native-basics:3:11')::uuid, 3, 'An XMLHttpRequest instance with an open connection', false),
  (md5('course-answer:react-native-basics:3:11:4')::uuid, md5('course-question:react-native-basics:3:11')::uuid, 4, 'A subscription object that emits network lifecycle events', false),
  (md5('course-answer:react-native-basics:3:12:1')::uuid, md5('course-question:react-native-basics:3:12')::uuid, 1, 'Network errors will otherwise cause the Metro bundler to terminate', false),
  (md5('course-answer:react-native-basics:3:12:2')::uuid, md5('course-question:react-native-basics:3:12')::uuid, 2, 'Errors thrown by fetch will be dropped silently if not caught', true),
  (md5('course-answer:react-native-basics:3:12:3')::uuid, md5('course-question:react-native-basics:3:12')::uuid, 3, 'React Native forces the entire operating system network stack to reset', false),
  (md5('course-answer:react-native-basics:3:12:4')::uuid, md5('course-question:react-native-basics:3:12')::uuid, 4, 'Uncaught network errors convert GET requests into POST retries', false),
  (md5('course-answer:react-native-basics:3:13:1')::uuid, md5('course-question:react-native-basics:3:13')::uuid, 1, 'Supply a JSON object to fetch''s third argument labelled `data`', false),
  (md5('course-answer:react-native-basics:3:13:2')::uuid, md5('course-question:react-native-basics:3:13')::uuid, 2, 'Set `method: ''POST''` and assign a stringified payload to `body` in the options object', true),
  (md5('course-answer:react-native-basics:3:13:3')::uuid, md5('course-question:react-native-basics:3:13')::uuid, 3, 'Invoke `fetch.post(url, payload)` using the built-in HTTP helper', false),
  (md5('course-answer:react-native-basics:3:13:4')::uuid, md5('course-question:react-native-basics:3:13')::uuid, 4, 'Configure `mode: ''upload''` and pass a FormData object to the URL path', false),
  (md5('course-answer:react-native-basics:3:14:1')::uuid, md5('course-question:react-native-basics:3:14')::uuid, 1, 'App Transport Security requires network requests to use HTTPS', true),
  (md5('course-answer:react-native-basics:3:14:2')::uuid, md5('course-question:react-native-basics:3:14')::uuid, 2, 'Connections are restricted to IPv6 addresses only', false),
  (md5('course-answer:react-native-basics:3:14:3')::uuid, md5('course-question:react-native-basics:3:14')::uuid, 3, 'All requests must include a valid CORS Access-Control-Allow-Origin header', false),
  (md5('course-answer:react-native-basics:3:14:4')::uuid, md5('course-question:react-native-basics:3:14')::uuid, 4, 'Requests must explicitly define ephemeral custom SSL certificates', false),
  (md5('course-answer:react-native-basics:3:15:1')::uuid, md5('course-question:react-native-basics:3:15')::uuid, 1, 'It is permitted only when connecting over cellular data', false),
  (md5('course-answer:react-native-basics:3:15:2')::uuid, md5('course-question:react-native-basics:3:15')::uuid, 2, 'It is automatically rerouted through a local WebSocket proxy', false),
  (md5('course-answer:react-native-basics:3:15:3')::uuid, md5('course-question:react-native-basics:3:15')::uuid, 3, 'It is blocked by default unless enabled in the application manifest', true),
  (md5('course-answer:react-native-basics:3:15:4')::uuid, md5('course-question:react-native-basics:3:15')::uuid, 4, 'It succeeds only if the request payload contains fewer than 1024 bytes', false)
on conflict (id) do update set text = excluded.text, is_correct = excluded.is_correct;

-- Quiz ui-design-fundamentals/1: Seeing like a designer quiz (15 questions)
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('course-quiz:ui-design-fundamentals:1')::uuid, md5('chapter:ui-design-fundamentals:1')::uuid, 'Seeing like a designer quiz', 1, true)
on conflict (id) do update set title = excluded.title, is_preview = excluded.is_preview;
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('course-question:ui-design-fundamentals:1:1')::uuid, md5('course-quiz:ui-design-fundamentals:1')::uuid, 1, 'According to the NHS design principles, what should you do when handling complex user journeys?', 'The principle ''Do the hard work to make it simple'' states that designers must understand what they are trying to solve rather than pushing complexity onto the people using the service.', 'https://service-manual.nhs.uk/design-system/design-principles'),
  (md5('course-question:ui-design-fundamentals:1:2')::uuid, md5('course-quiz:ui-design-fundamentals:1')::uuid, 2, 'According to the U.S. Web Design System (USWDS), which action helps teams start with real user needs?', 'USWDS recommends using prototypes early in the project to test your team''s assumptions and solutions with real people, ideally in the field.', 'https://designsystem.digital.gov/design-principles/'),
  (md5('course-question:ui-design-fundamentals:1:3')::uuid, md5('course-quiz:ui-design-fundamentals:1')::uuid, 3, 'Under the USWDS principle ''Earn trust'', which practical measure is recommended to maintain confidence in your service?', 'USWDS highlights that trust is built through reliability and solid engineering, specifically considering whether users can undo actions or edit data they have entered.', 'https://designsystem.digital.gov/design-principles/'),
  (md5('course-question:ui-design-fundamentals:1:4')::uuid, md5('course-quiz:ui-design-fundamentals:1')::uuid, 4, 'What does the NHS principle ''Test your assumptions'' specifically instruct teams to avoid?', 'The NHS design principles instruct teams to observe behaviour and gather evidence from real people rather than relying on hunches.', 'https://service-manual.nhs.uk/design-system/design-principles'),
  (md5('course-question:ui-design-fundamentals:1:5')::uuid, md5('course-quiz:ui-design-fundamentals:1')::uuid, 5, 'According to the USWDS guidance on embracing accessibility, how should accessibility requirements be viewed?', 'USWDS states that accessibility affects everybody and encourages teams to celebrate accessibility requirements as design constraints that create better products for all users.', 'https://designsystem.digital.gov/design-principles/'),
  (md5('course-question:ui-design-fundamentals:1:6')::uuid, md5('course-quiz:ui-design-fundamentals:1')::uuid, 6, 'In semantic HTML structure, what condition must be met for a `<section>` element to expose its landmark role to assistive technology?', 'A `<section>` element requires an accessible name (for example, provided by `aria-label`) for its implicit ARIA role of region to be visible to assistive technology.', 'https://web.dev/learn/accessibility/structure'),
  (md5('course-question:ui-design-fundamentals:1:7')::uuid, md5('course-quiz:ui-design-fundamentals:1')::uuid, 7, 'Why should you decouple CSS styles from HTML heading tags (`<h1>` to `<h6>`)?', 'Decoupling CSS styles from heading elements gives you flexibility in visual presentation without skipping heading levels, which assistive technology users rely on for navigation.', 'https://web.dev/learn/accessibility/structure'),
  (md5('course-question:ui-design-fundamentals:1:8')::uuid, md5('course-quiz:ui-design-fundamentals:1')::uuid, 8, 'Why does web accessibility guidance strongly caution against using positive `tabindex` values like `tabindex="1"`?', 'Positive tabindex values disrupt the normal document flow by jumping ahead of standard DOM elements, which can confuse and frustrate keyboard users.', 'https://web.dev/learn/accessibility/focus'),
  (md5('course-question:ui-design-fundamentals:1:9')::uuid, md5('course-quiz:ui-design-fundamentals:1')::uuid, 9, 'What is the primary effect of adding `tabindex="-1"` to an element?', 'A negative tabindex removes an element from the natural sequential keyboard navigation order, though it can still receive focus programmatically using JavaScript.', 'https://web.dev/learn/accessibility/focus'),
  (md5('course-question:ui-design-fundamentals:1:10')::uuid, md5('course-quiz:ui-design-fundamentals:1')::uuid, 10, 'What is the primary purpose of a skip link on a web page?', 'Skip links are anchor links placed early on a page that let keyboard users jump over repetitive navigation menus straight to the main content.', 'https://web.dev/learn/accessibility/focus'),
  (md5('course-question:ui-design-fundamentals:1:11')::uuid, md5('course-quiz:ui-design-fundamentals:1')::uuid, 11, 'Why does the GOV.UK Design System combine yellow and black for its focus states?', 'GOV.UK combines yellow (which contrasts against dark backgrounds) with a thick black border (which contrasts against light backgrounds) to meet WCAG non-text contrast requirements across all site backgrounds.', 'https://design-system.service.gov.uk/get-started/focus-states/'),
  (md5('course-question:ui-design-fundamentals:1:12')::uuid, md5('course-quiz:ui-design-fundamentals:1')::uuid, 12, 'What is the recommended minimum colour contrast ratio for custom focus indicators against adjacent backgrounds?', 'Web accessibility guidelines recommend adhering to at least a 3:1 colour contrast ratio for focus indicators against the background.', 'https://web.dev/learn/accessibility/focus'),
  (md5('course-question:ui-design-fundamentals:1:13')::uuid, md5('course-quiz:ui-design-fundamentals:1')::uuid, 13, 'In responsive design, why does relying solely on an unlabelled icon button create ''mystery meat'' navigation?', 'An unlabelled icon button forces users to guess its function, leaving them unsure of where it leads until they interact with it.', 'https://web.dev/learn/design/ui-patterns'),
  (md5('course-question:ui-design-fundamentals:1:14')::uuid, md5('course-quiz:ui-design-fundamentals:1')::uuid, 14, 'When using an overflow carousel on compact screens, why should cards avoid filling the entire viewport width?', 'If a card takes up the entire viewport width, users receive no visual cue that additional content is available beyond the edge.', 'https://web.dev/learn/design/ui-patterns'),
  (md5('course-question:ui-design-fundamentals:1:15')::uuid, md5('course-quiz:ui-design-fundamentals:1')::uuid, 15, 'According to Fitts''s Law and responsive interaction guidelines, why should you avoid shrinking interactive targets for fine pointers?', 'Fitts''s Law demonstrates that smaller targets demand greater concentration even when using precise devices like a mouse; larger target areas benefit all users.', 'https://web.dev/learn/design/interaction')
on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, reference_url = excluded.reference_url;
update public.quiz_answers set is_correct = false where question_id in (select id from public.quiz_questions where quiz_id = md5('course-quiz:ui-design-fundamentals:1')::uuid);
insert into public.quiz_answers (id, question_id, position, text, is_correct) values
  (md5('course-answer:ui-design-fundamentals:1:1:1')::uuid, md5('course-question:ui-design-fundamentals:1:1')::uuid, 1, 'Take the time to understand the problem so you do not push complexity onto the user', true),
  (md5('course-answer:ui-design-fundamentals:1:1:2')::uuid, md5('course-question:ui-design-fundamentals:1:1')::uuid, 2, 'Break every journey into at least five sequential steps regardless of topic', false),
  (md5('course-answer:ui-design-fundamentals:1:1:3')::uuid, md5('course-question:ui-design-fundamentals:1:1')::uuid, 3, 'Direct users to phone support whenever an online task involves multiple choices', false),
  (md5('course-answer:ui-design-fundamentals:1:1:4')::uuid, md5('course-question:ui-design-fundamentals:1:1')::uuid, 4, 'Provide downloadable instruction manuals before allowing users to begin', false),
  (md5('course-answer:ui-design-fundamentals:1:2:1')::uuid, md5('course-question:ui-design-fundamentals:1:2')::uuid, 1, 'Relying primarily on internal team preferences during early development', false),
  (md5('course-answer:ui-design-fundamentals:1:2:2')::uuid, md5('course-question:ui-design-fundamentals:1:2')::uuid, 2, 'Using prototypes to test assumptions and solutions with real people', true),
  (md5('course-answer:ui-design-fundamentals:1:2:3')::uuid, md5('course-question:ui-design-fundamentals:1:2')::uuid, 3, 'Postponing user testing until after the product is fully deployed', false),
  (md5('course-answer:ui-design-fundamentals:1:2:4')::uuid, md5('course-question:ui-design-fundamentals:1:2')::uuid, 4, 'Surveying only individuals who have extensive technical backgrounds', false),
  (md5('course-answer:ui-design-fundamentals:1:3:1')::uuid, md5('course-question:ui-design-fundamentals:1:3')::uuid, 1, 'Removing all external links and disabling browser navigation controls', false),
  (md5('course-answer:ui-design-fundamentals:1:3:2')::uuid, md5('course-question:ui-design-fundamentals:1:3')::uuid, 2, 'Ensuring users can undo actions or edit data they have added to the system', true),
  (md5('course-answer:ui-design-fundamentals:1:3:3')::uuid, md5('course-question:ui-design-fundamentals:1:3')::uuid, 3, 'Keeping data schemas undisclosed and replacing plain language with technical terms', false),
  (md5('course-answer:ui-design-fundamentals:1:3:4')::uuid, md5('course-question:ui-design-fundamentals:1:3')::uuid, 4, 'Refreshing the visual theme each week to show ongoing engineering work', false),
  (md5('course-answer:ui-design-fundamentals:1:4:1')::uuid, md5('course-question:ui-design-fundamentals:1:4')::uuid, 1, 'Working directly with subject matter experts', false),
  (md5('course-answer:ui-design-fundamentals:1:4:2')::uuid, md5('course-question:ui-design-fundamentals:1:4')::uuid, 2, 'Observing real behaviour during testing sessions', false),
  (md5('course-answer:ui-design-fundamentals:1:4:3')::uuid, md5('course-question:ui-design-fundamentals:1:4')::uuid, 3, 'Relying on hunches instead of gathered evidence', true),
  (md5('course-answer:ui-design-fundamentals:1:4:4')::uuid, md5('course-question:ui-design-fundamentals:1:4')::uuid, 4, 'Consulting existing healthcare research', false),
  (md5('course-answer:ui-design-fundamentals:1:5:1')::uuid, md5('course-question:ui-design-fundamentals:1:5')::uuid, 1, 'As an optional post-launch polishing checklist', false),
  (md5('course-answer:ui-design-fundamentals:1:5:2')::uuid, md5('course-question:ui-design-fundamentals:1:5')::uuid, 2, 'As design constraints that help create a better product for everyone', true),
  (md5('course-answer:ui-design-fundamentals:1:5:3')::uuid, md5('course-question:ui-design-fundamentals:1:5')::uuid, 3, 'As rules that apply only when designing specifically for desktop computers', false),
  (md5('course-answer:ui-design-fundamentals:1:5:4')::uuid, md5('course-question:ui-design-fundamentals:1:5')::uuid, 4, 'As technical tasks handled exclusively by front-end engineers', false),
  (md5('course-answer:ui-design-fundamentals:1:6:1')::uuid, md5('course-question:ui-design-fundamentals:1:6')::uuid, 1, 'It must contain an accessible name such as an `aria-label`', true),
  (md5('course-answer:ui-design-fundamentals:1:6:2')::uuid, md5('course-question:ui-design-fundamentals:1:6')::uuid, 2, 'It must be placed directly inside a `<header>` element', false),
  (md5('course-answer:ui-design-fundamentals:1:6:3')::uuid, md5('course-question:ui-design-fundamentals:1:6')::uuid, 3, 'It must use a `role="main"` attribute explicitly', false),
  (md5('course-answer:ui-design-fundamentals:1:6:4')::uuid, md5('course-question:ui-design-fundamentals:1:6')::uuid, 4, 'It must contain at least three distinct paragraphs', false),
  (md5('course-answer:ui-design-fundamentals:1:7:1')::uuid, md5('course-question:ui-design-fundamentals:1:7')::uuid, 1, 'To allow screen readers to ignore visual styles entirely', false),
  (md5('course-answer:ui-design-fundamentals:1:7:2')::uuid, md5('course-question:ui-design-fundamentals:1:7')::uuid, 2, 'To reduce the number of landmarks needed across the layout', false),
  (md5('course-answer:ui-design-fundamentals:1:7:3')::uuid, md5('course-question:ui-design-fundamentals:1:7')::uuid, 3, 'To make smaller headings inherit default table formatting', false),
  (md5('course-answer:ui-design-fundamentals:1:7:4')::uuid, md5('course-question:ui-design-fundamentals:1:7')::uuid, 4, 'To style headings flexibly while maintaining sequential heading level order', true),
  (md5('course-answer:ui-design-fundamentals:1:8:1')::uuid, md5('course-question:ui-design-fundamentals:1:8')::uuid, 1, 'They disable keyboard navigation on desktop browsers', false),
  (md5('course-answer:ui-design-fundamentals:1:8:2')::uuid, md5('course-question:ui-design-fundamentals:1:8')::uuid, 2, 'They override the natural DOM order and create confusing focus jumps', true),
  (md5('course-answer:ui-design-fundamentals:1:8:3')::uuid, md5('course-question:ui-design-fundamentals:1:8')::uuid, 3, 'They permanently hide the element from sighted keyboard users', false),
  (md5('course-answer:ui-design-fundamentals:1:8:4')::uuid, md5('course-question:ui-design-fundamentals:1:8')::uuid, 4, 'They prevent form elements from submitting their input values', false),
  (md5('course-answer:ui-design-fundamentals:1:9:1')::uuid, md5('course-question:ui-design-fundamentals:1:9')::uuid, 1, 'It permanently hides the element visually from the screen', false),
  (md5('course-answer:ui-design-fundamentals:1:9:2')::uuid, md5('course-question:ui-design-fundamentals:1:9')::uuid, 2, 'It makes the element focusable before all elements with `tabindex="0"`', false),
  (md5('course-answer:ui-design-fundamentals:1:9:3')::uuid, md5('course-question:ui-design-fundamentals:1:9')::uuid, 3, 'It removes the element from the natural tab order while allowing focus via script', true),
  (md5('course-answer:ui-design-fundamentals:1:9:4')::uuid, md5('course-question:ui-design-fundamentals:1:9')::uuid, 4, 'It resets the element''s CSS outline to the browser default', false),
  (md5('course-answer:ui-design-fundamentals:1:10:1')::uuid, md5('course-question:ui-design-fundamentals:1:10')::uuid, 1, 'To jump directly to external terms and conditions links', false),
  (md5('course-answer:ui-design-fundamentals:1:10:2')::uuid, md5('course-question:ui-design-fundamentals:1:10')::uuid, 2, 'To allow keyboard users to bypass repetitive header navigation', true),
  (md5('course-answer:ui-design-fundamentals:1:10:3')::uuid, md5('course-question:ui-design-fundamentals:1:10')::uuid, 3, 'To refresh the page content without resetting form fields', false),
  (md5('course-answer:ui-design-fundamentals:1:10:4')::uuid, md5('course-question:ui-design-fundamentals:1:10')::uuid, 4, 'To redirect mobile users to a separate native application', false),
  (md5('course-answer:ui-design-fundamentals:1:11:1')::uuid, md5('course-question:ui-design-fundamentals:1:11')::uuid, 1, 'Yellow has high contrast on dark backgrounds and black has high contrast on light backgrounds', true),
  (md5('course-answer:ui-design-fundamentals:1:11:2')::uuid, md5('course-question:ui-design-fundamentals:1:11')::uuid, 2, 'These are the only colours permitted by default browser rendering engines', false),
  (md5('course-answer:ui-design-fundamentals:1:11:3')::uuid, md5('course-question:ui-design-fundamentals:1:11')::uuid, 3, 'The combination eliminates the need to support high-contrast operating system modes', false),
  (md5('course-answer:ui-design-fundamentals:1:11:4')::uuid, md5('course-question:ui-design-fundamentals:1:11')::uuid, 4, 'Black and yellow reduce battery usage on mobile touchscreen displays', false),
  (md5('course-answer:ui-design-fundamentals:1:12:1')::uuid, md5('course-question:ui-design-fundamentals:1:12')::uuid, 1, '1.5:1', false),
  (md5('course-answer:ui-design-fundamentals:1:12:2')::uuid, md5('course-question:ui-design-fundamentals:1:12')::uuid, 2, '2:1', false),
  (md5('course-answer:ui-design-fundamentals:1:12:3')::uuid, md5('course-question:ui-design-fundamentals:1:12')::uuid, 3, '3:1', true),
  (md5('course-answer:ui-design-fundamentals:1:12:4')::uuid, md5('course-question:ui-design-fundamentals:1:12')::uuid, 4, '7:1', false),
  (md5('course-answer:ui-design-fundamentals:1:13:1')::uuid, md5('course-question:ui-design-fundamentals:1:13')::uuid, 1, 'Users cannot know what the control does until they tap or click it', true),
  (md5('course-answer:ui-design-fundamentals:1:13:2')::uuid, md5('course-question:ui-design-fundamentals:1:13')::uuid, 2, 'Icons require extra network bandwidth to load compared to text strings', false),
  (md5('course-answer:ui-design-fundamentals:1:13:3')::uuid, md5('course-question:ui-design-fundamentals:1:13')::uuid, 3, 'Screen readers refuse to focus on elements that use vector graphics', false),
  (md5('course-answer:ui-design-fundamentals:1:13:4')::uuid, md5('course-question:ui-design-fundamentals:1:13')::uuid, 4, 'Modern browsers automatically remove unlabelled buttons from the DOM', false),
  (md5('course-answer:ui-design-fundamentals:1:14:1')::uuid, md5('course-question:ui-design-fundamentals:1:14')::uuid, 1, 'Filling the full width causes browsers to disable smooth scrolling', false),
  (md5('course-answer:ui-design-fundamentals:1:14:2')::uuid, md5('course-question:ui-design-fundamentals:1:14')::uuid, 2, 'Leaving the next card partially visible signals that more content exists off-screen', true),
  (md5('course-answer:ui-design-fundamentals:1:14:3')::uuid, md5('course-question:ui-design-fundamentals:1:14')::uuid, 3, 'Cards that fill the width automatically trigger horizontal page refreshes', false),
  (md5('course-answer:ui-design-fundamentals:1:14:4')::uuid, md5('course-question:ui-design-fundamentals:1:14')::uuid, 4, 'CSS scroll snap only works when elements occupy less than 50% of the screen', false),
  (md5('course-answer:ui-design-fundamentals:1:15:1')::uuid, md5('course-question:ui-design-fundamentals:1:15')::uuid, 1, 'Fine pointers cannot register clicks on elements smaller than 48 pixels', false),
  (md5('course-answer:ui-design-fundamentals:1:15:2')::uuid, md5('course-question:ui-design-fundamentals:1:15')::uuid, 2, 'Smaller targets require more concentration to hit, whereas larger targets benefit everyone', true),
  (md5('course-answer:ui-design-fundamentals:1:15:3')::uuid, md5('course-question:ui-design-fundamentals:1:15')::uuid, 3, 'Operating systems disable hover effects when buttons are made smaller', false),
  (md5('course-answer:ui-design-fundamentals:1:15:4')::uuid, md5('course-question:ui-design-fundamentals:1:15')::uuid, 4, 'Touchscreens automatically magnify buttons whenever a mouse is disconnected', false)
on conflict (id) do update set text = excluded.text, is_correct = excluded.is_correct;

-- Quiz ui-design-fundamentals/2: Typography and colour quiz (15 questions)
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('course-quiz:ui-design-fundamentals:2')::uuid, md5('chapter:ui-design-fundamentals:2')::uuid, 'Typography and colour quiz', 1, false)
on conflict (id) do update set title = excluded.title, is_preview = excluded.is_preview;
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('course-question:ui-design-fundamentals:2:1')::uuid, md5('course-quiz:ui-design-fundamentals:2')::uuid, 1, 'Which font format is recommended for web delivery due to its broad browser support and superior compression?', 'WOFF2 offers the best compression gains and wide browser support, making it the recommended format for web fonts.', 'https://web.dev/learn/design/typography'),
  (md5('course-question:ui-design-fundamentals:2:2')::uuid, md5('course-quiz:ui-design-fundamentals:2')::uuid, 2, 'According to GOV.UK Design System guidance, when must a service use the GDS Transport font?', 'The GOV.UK Design System requires services on the service.gov.uk subdomain to use GDS Transport, whereas external services must use an alternative typeface.', 'https://design-system.service.gov.uk/styles/typeface/'),
  (md5('course-question:ui-design-fundamentals:2:3')::uuid, md5('course-quiz:ui-design-fundamentals:2')::uuid, 3, 'When preloading a web font in HTML using `<link rel="preload" as="font">`, which attribute must always be included?', 'The crossorigin attribute is required when preloading fonts, even if the font files are hosted on the same origin.', 'https://web.dev/learn/design/typography'),
  (md5('course-question:ui-design-fundamentals:2:4')::uuid, md5('course-quiz:ui-design-fundamentals:2')::uuid, 4, 'What rendering behaviour occurs when applying `font-display: swap` in CSS?', 'Using font-display: swap shows the system fallback font immediately and swaps in the web font once it finishes downloading.', 'https://web.dev/learn/design/typography'),
  (md5('course-question:ui-design-fundamentals:2:5')::uuid, md5('course-quiz:ui-design-fundamentals:2')::uuid, 5, 'What is the primary performance benefit of using a variable font instead of separate standard font files?', 'A variable font contains information for multiple weights and styles in a single file, typically resulting in a smaller overall download than several individual font files.', 'https://web.dev/learn/design/typography'),
  (md5('course-question:ui-design-fundamentals:2:6')::uuid, md5('course-quiz:ui-design-fundamentals:2')::uuid, 6, 'Why does every step on the GOV.UK type scale pair a font size with a line height calculated in a multiple of 5px?', 'Using line heights calculated in multiples of 5px creates a consistent vertical rhythm, improving readability and making layouts easier to scan.', 'https://design-system.service.gov.uk/styles/type-scale/'),
  (md5('course-question:ui-design-fundamentals:2:7')::uuid, md5('course-quiz:ui-design-fundamentals:2')::uuid, 7, 'At what viewport width does GOV.UK Frontend switch from the small screen type scale to the large screen scale?', 'The GOV.UK type scale switches to the large screen version when the screen is wider than the 640px tablet breakpoint.', 'https://design-system.service.gov.uk/styles/type-scale/'),
  (md5('course-question:ui-design-fundamentals:2:8')::uuid, md5('course-quiz:ui-design-fundamentals:2')::uuid, 8, 'In GOV.UK Frontend Sass, what distinguishes the `govuk-font-size` mixin from the `govuk-font` mixin?', 'govuk-font-size only applies font size and line height, whereas govuk-font also includes font family rules like New Transport and weight options.', 'https://design-system.service.gov.uk/styles/type-scale/'),
  (md5('course-question:ui-design-fundamentals:2:9')::uuid, md5('course-quiz:ui-design-fundamentals:2')::uuid, 9, 'In the updated GOV.UK Frontend type scale, how do points 16 and 19 behave across screen sizes?', 'In the updated scale, points 16 and 19 remain constant at 16px and 19px across all screen sizes to maintain readability.', 'https://design-system.service.gov.uk/get-started/new-type-scale/'),
  (md5('course-question:ui-design-fundamentals:2:10')::uuid, md5('course-quiz:ui-design-fundamentals:2')::uuid, 10, 'Why does web.dev caution against declaring `font-size` using only the `vw` viewport unit?', 'Declaring font-size with only vw prevents users from resizing text; mixing in relative units with calc() preserves zoom functionality.', 'https://web.dev/learn/design/typography'),
  (md5('course-question:ui-design-fundamentals:2:11')::uuid, md5('course-quiz:ui-design-fundamentals:2')::uuid, 11, 'What is the minimum WCAG Level AA contrast ratio required for regular-sized text against its background?', 'WCAG Level AA requires regular-sized text (under 24px, or under 18.5px bold) to achieve a contrast ratio of at least 4.5:1.', 'https://web.dev/learn/accessibility/color-contrast'),
  (md5('course-question:ui-design-fundamentals:2:12')::uuid, md5('course-quiz:ui-design-fundamentals:2')::uuid, 12, 'Under WCAG contrast guidelines, what minimum contrast ratio is required for large-sized text and essential icons?', 'Large text (at least 24px, or 18.5px bold) and essential graphical elements like icons need a 3:1 contrast ratio to meet WCAG Level AA.', 'https://web.dev/learn/accessibility/color-contrast'),
  (md5('course-question:ui-design-fundamentals:2:13')::uuid, md5('course-quiz:ui-design-fundamentals:2')::uuid, 13, 'How can a website provide distinct browser theme colours for light and dark operating system modes in HTML?', 'Browsers support multiple meta theme-color elements paired with prefers-color-scheme media attributes to adapt browser chrome for light and dark themes.', 'https://web.dev/learn/design/theming'),
  (md5('course-question:ui-design-fundamentals:2:14')::uuid, md5('course-quiz:ui-design-fundamentals:2')::uuid, 14, 'In the GOV.UK Design System, what is the main reason to use `govuk-functional-colour` instead of hard-coded hex codes?', 'Using govuk-functional-colour links styles to functional roles, ensuring services automatically adopt updated colour values when the design system changes.', 'https://design-system.service.gov.uk/styles/colour/'),
  (md5('course-question:ui-design-fundamentals:2:15')::uuid, md5('course-quiz:ui-design-fundamentals:2')::uuid, 15, 'Which CSS property allows you to style form controls such as checkboxes and radio buttons to match a theme colour?', 'The accent-color property in CSS enables developers to style user-interface controls like checkboxes and radio buttons with custom theme colours.', 'https://web.dev/learn/design/theming')
on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, reference_url = excluded.reference_url;
update public.quiz_answers set is_correct = false where question_id in (select id from public.quiz_questions where quiz_id = md5('course-quiz:ui-design-fundamentals:2')::uuid);
