-- Quiz ui-design-fundamentals/3: Layout and spacing quiz (15 questions)
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('course-quiz:ui-design-fundamentals:3')::uuid, md5('chapter:ui-design-fundamentals:3')::uuid, 'Layout and spacing quiz', 1, false)
on conflict (id) do update set title = excluded.title, is_preview = excluded.is_preview;
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('course-question:ui-design-fundamentals:3:1')::uuid, md5('course-quiz:ui-design-fundamentals:3')::uuid, 1, 'In CSS layout, what is one major advantage of using CSS grid over flexbox for page-level macro layouts?', 'With flexbox, each column requires a separate rule to define how much space it takes up. In CSS grid, that sizing information is encapsulated in a single rule on the containing element.', 'https://web.dev/learn/design/macro-layouts'),
  (md5('course-question:ui-design-fundamentals:3:2')::uuid, md5('course-quiz:ui-design-fundamentals:3')::uuid, 2, 'When creating a responsive card collection without media queries, what happens in flexbox if the final row does not have enough cards to fill it?', 'If there are not enough cards to fill the final row, flexbox cards stretch to fill the remaining space. CSS grid preserves column and row alignment.', 'https://web.dev/learn/design/macro-layouts'),
  (md5('course-question:ui-design-fundamentals:3:3')::uuid, md5('course-quiz:ui-design-fundamentals:3')::uuid, 3, 'According to the GOV.UK Design System layout guidance, why is a two-thirds layout recommended for most pages on desktop devices?', 'A two-thirds layout prevents lines of text from becoming too long to read easily on desktop screens, targeting no more than 75 characters per line.', 'https://design-system.service.gov.uk/styles/layout/'),
  (md5('course-question:ui-design-fundamentals:3:4')::uuid, md5('course-quiz:ui-design-fundamentals:3')::uuid, 4, 'What is the default maximum page width specified in the GOV.UK Design System layout guidance?', 'The default maximum page width in the GOV.UK Design System is 1020px, though it can be made wider if specific content requires it.', 'https://design-system.service.gov.uk/styles/layout/'),
  (md5('course-question:ui-design-fundamentals:3:5')::uuid, md5('course-quiz:ui-design-fundamentals:3')::uuid, 5, 'Which CSS declaration creates a responsive macro grid for cards that automatically fits as many columns of at least 15em as possible?', 'Using repeat(auto-fill, minmax(15em, 1fr)) instructs the browser to place as many 15em items as fit on a line, expanding remaining space with 1fr.', 'https://web.dev/learn/design/macro-layouts'),
  (md5('course-question:ui-design-fundamentals:3:6')::uuid, md5('course-quiz:ui-design-fundamentals:3')::uuid, 6, 'In the GOV.UK Design System responsive spacing scale, which breakpoint triggers the switch from small-screen spacing to large-screen spacing?', 'In GOV.UK, large-screen spacing is used when the screen is wider than the tablet breakpoint of 640px.', 'https://design-system.service.gov.uk/styles/spacing/'),
  (md5('course-question:ui-design-fundamentals:3:7')::uuid, md5('course-quiz:ui-design-fundamentals:3')::uuid, 7, 'In the NHS digital service manual responsive spacing scale, which spacing units stay exactly the same across all screen sizes?', 'In the NHS responsive spacing scale, spacing for the smallest units (0 to 2) stays the same for all screen sizes.', 'https://service-manual.nhs.uk/design-system/styles/spacing'),
  (md5('course-question:ui-design-fundamentals:3:8')::uuid, md5('course-quiz:ui-design-fundamentals:3')::uuid, 8, 'On which base multiple are spacing unit tokens in the U.S. Web Design System (USWDS) primarily calculated?', 'USWDS spacing unit tokens in utilities and component CSS are based primarily on multiples of 8px.', 'https://designsystem.digital.gov/design-tokens/spacing-units/'),
  (md5('course-question:ui-design-fundamentals:3:9')::uuid, md5('course-quiz:ui-design-fundamentals:3')::uuid, 9, 'In the GOV.UK Design System, which Sass helper should you use if you need static spacing that remains identical on all screen sizes?', 'For the static spacing scale in GOV.UK, you use the govuk-spacing function, such as govuk-spacing(6). The govuk-responsive mixins apply responsive spacing instead.', 'https://design-system.service.gov.uk/styles/spacing/'),
  (md5('course-question:ui-design-fundamentals:3:10')::uuid, md5('course-quiz:ui-design-fundamentals:3')::uuid, 10, 'When applying spacing through utility classes in USWDS, which type of token is used exclusively when both forms exist?', 'While USWDS mixins accept numeric or string tokens, utility classes use unquoted string tokens exclusively when they exist (such as .margin-x-neg-2).', 'https://designsystem.digital.gov/design-tokens/spacing-units/'),
  (md5('course-question:ui-design-fundamentals:3:11')::uuid, md5('course-quiz:ui-design-fundamentals:3')::uuid, 11, 'In the GOV.UK layout system, what is the specific role of the govuk-width-container wrapper?', 'The govuk-width-container wrapper sets the maximum width of the content, but does not add any vertical margin or padding.', 'https://design-system.service.gov.uk/styles/layout/'),
  (md5('course-question:ui-design-fundamentals:3:12')::uuid, md5('course-quiz:ui-design-fundamentals:3')::uuid, 12, 'In the GOV.UK page template, which block option should you use to place a Back link component immediately after the opening width container?', 'The containerStart block adds content directly after the opening govuk-width-container div, which is where components like back links and breadcrumbs belong.', 'https://design-system.service.gov.uk/styles/page-template/'),
  (md5('course-question:ui-design-fundamentals:3:13')::uuid, md5('course-quiz:ui-design-fundamentals:3')::uuid, 13, 'What is the main distinction between a macro layout and a micro layout in web design?', 'Macro layouts describe the large, page-level organisation of an interface, while micro layouts govern smaller, self-contained components within the page.', 'https://web.dev/learn/design/micro-layouts'),
  (md5('course-question:ui-design-fundamentals:3:14')::uuid, md5('course-quiz:ui-design-fundamentals:3')::uuid, 14, 'To enable container queries based on an element''s width in CSS, which property and value must be declared on that container element?', 'Declaring container-type: inline-size instructs the browser to query the inline dimension (width in horizontal writing modes) of that container.', 'https://web.dev/learn/design/micro-layouts'),
  (md5('course-question:ui-design-fundamentals:3:15')::uuid, md5('course-quiz:ui-design-fundamentals:3')::uuid, 15, 'Why are container queries particularly useful for components that might be placed in either a main content area or a sidebar?', 'Container queries allow components to respond directly to the dimensions of their parent container, ensuring they adapt correctly whether situated in a wide main column or a narrow sidebar.', 'https://web.dev/learn/design/micro-layouts')
on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, reference_url = excluded.reference_url;
update public.quiz_answers set is_correct = false where question_id in (select id from public.quiz_questions where quiz_id = md5('course-quiz:ui-design-fundamentals:3')::uuid);
insert into public.quiz_answers (id, question_id, position, text, is_correct) values
  (md5('course-answer:ui-design-fundamentals:3:1:1')::uuid, md5('course-question:ui-design-fundamentals:3:1')::uuid, 1, 'Grid allows the entire column structure to be defined on the containing element alone', true),
  (md5('course-answer:ui-design-fundamentals:3:1:2')::uuid, md5('course-question:ui-design-fundamentals:3:1')::uuid, 2, 'Grid automatically disables media queries across all browser viewports', false),
  (md5('course-answer:ui-design-fundamentals:3:1:3')::uuid, md5('course-question:ui-design-fundamentals:3:1')::uuid, 3, 'Flexbox requires all child elements to have identical inline pixel widths', false),
  (md5('course-answer:ui-design-fundamentals:3:1:4')::uuid, md5('course-question:ui-design-fundamentals:3:1')::uuid, 4, 'Flexbox cannot align items horizontally in modern web browsers', false),
  (md5('course-answer:ui-design-fundamentals:3:2:1')::uuid, md5('course-question:ui-design-fundamentals:3:2')::uuid, 1, 'The remaining cards hide automatically until the viewport expands', false),
