-- Quiz python-for-everyone/1: Your first program quiz (15 questions)
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('course-quiz:python-for-everyone:1')::uuid, md5('chapter:python-for-everyone:1')::uuid, 'Your first program quiz', 1, true)
on conflict (id) do update set title = excluded.title, is_preview = excluded.is_preview;
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('course-question:python-for-everyone:1:1')::uuid, md5('course-quiz:python-for-everyone:1')::uuid, 1, 'According to the Python tutorial, which design choice helps make Python programs substantially shorter than equivalent C, C++, or Java programs?', 'Python groups statements using indentation rather than brackets and requires no variable or argument declarations, keeping code concise.', 'https://docs.python.org/3.15/tutorial/appetite.html'),
  (md5('course-question:python-for-everyone:1:2')::uuid, md5('course-quiz:python-for-everyone:1')::uuid, 2, 'After which television show was the Python programming language named?', 'Python was named after the BBC television comedy series Monty Python''s Flying Circus and has nothing to do with reptiles.', 'https://docs.python.org/3.15/tutorial/appetite.html'),
  (md5('course-question:python-for-everyone:1:3')::uuid, md5('course-quiz:python-for-everyone:1')::uuid, 3, 'What major development advantage does Python''s nature as an interpreted language provide compared to compiled languages?', 'Because no separate compilation and linking step is needed, Python avoids the slow compile-and-link cycle, speeding up development.', 'https://docs.python.org/3.15/tutorial/appetite.html'),
  (md5('course-question:python-for-everyone:1:4')::uuid, md5('course-quiz:python-for-everyone:1')::uuid, 4, 'On Windows, what happens when you run `python` or `py` if no Python runtimes are currently installed?', 'When no version is requested and no runtimes are installed, the Python install manager automatically downloads and installs the current release.', 'https://docs.python.org/3.15/using/windows.html'),
  (md5('course-question:python-for-everyone:1:5')::uuid, md5('course-quiz:python-for-everyone:1')::uuid, 5, 'Which command can you run in PowerShell or Command Prompt to view runtimes in the online index that can be installed?', 'The `py list --online` command searches the online index for Python runtimes that can be installed using `py install`.', 'https://docs.python.org/3.15/using/windows.html'),
  (md5('course-question:python-for-everyone:1:6')::uuid, md5('course-quiz:python-for-everyone:1')::uuid, 6, 'After installing Python from the official installer package on macOS, why should you double-click `Install Certificates.command`?', 'Double-clicking `Install Certificates.command` opens a terminal window to download and configure SSL root certificates for secure network connections.', 'https://docs.python.org/3.15/using/mac.html'),
  (md5('course-question:python-for-everyone:1:7')::uuid, md5('course-quiz:python-for-everyone:1')::uuid, 7, 'In which directory does the default python.org installer on macOS place the Python framework?', 'The installer places the framework in `/Library/Frameworks/Python.framework`, with command shortcuts added to `/usr/local/bin/`.', 'https://docs.python.org/3.15/using/mac.html'),
  (md5('course-question:python-for-everyone:1:8')::uuid, md5('course-quiz:python-for-everyone:1')::uuid, 8, 'What characters make up the primary prompt when the Python interpreter is running in interactive mode?', 'In interactive mode, Python prompts for commands with the primary prompt, which consists of three greater-than characters (`>>>`).', 'https://docs.python.org/3.15/tutorial/interpreter.html'),
  (md5('course-question:python-for-everyone:1:9')::uuid, md5('course-quiz:python-for-everyone:1')::uuid, 9, 'How can you execute a Python statement directly from your operating system shell without opening an interactive session?', 'Running `python -c command` tells Python to execute the specified statement directly from the command line.', 'https://docs.python.org/3.15/tutorial/interpreter.html'),
  (md5('course-question:python-for-everyone:1:10')::uuid, md5('course-quiz:python-for-everyone:1')::uuid, 10, 'What is the behaviour of a hash character (`#`) placed inside a string literal, such as `"# Hello"`?', 'A comment begins with `#` outside string literals; when placed inside quotes, the hash symbol is simply part of the string.', 'https://docs.python.org/3.15/tutorial/introduction.html'),
  (md5('course-question:python-for-everyone:1:11')::uuid, md5('course-quiz:python-for-everyone:1')::uuid, 11, 'What does the `print()` function insert between multiple comma-separated arguments by default?', 'When printing multiple items separated by commas, the `print()` function automatically separates them with a space character by default.', 'https://github.com/openstax/osbooks-introduction-python-programming/tree/2825b114221917bea5ae328a94e484b4da8a93ca'),
  (md5('course-question:python-for-everyone:1:12')::uuid, md5('course-quiz:python-for-everyone:1')::uuid, 12, 'What happens if you attempt to evaluate a variable that has not been defined or assigned a value?', 'A variable exists only once a value is assigned to it; attempting to access an undefined variable raises a `NameError`.', 'https://docs.python.org/3.15/tutorial/introduction.html'),
  (md5('course-question:python-for-everyone:1:13')::uuid, md5('course-quiz:python-for-everyone:1')::uuid, 13, 'What data type is always returned by the classic division operator (`/`) in Python?', 'In Python, division using the `/` operator always returns a floating-point number (`float`), even when the result divides evenly.', 'https://docs.python.org/3.15/tutorial/introduction.html'),
  (md5('course-question:python-for-everyone:1:14')::uuid, md5('course-quiz:python-for-everyone:1')::uuid, 14, 'Which of the following is an invalid variable name in Python?', 'Python variable names may contain letters, digits, and underscores, but they cannot start with a digit.', 'https://github.com/openstax/osbooks-introduction-python-programming/tree/2825b114221917bea5ae328a94e484b4da8a93ca'),
  (md5('course-question:python-for-everyone:1:15')::uuid, md5('course-quiz:python-for-everyone:1')::uuid, 15, 'Which built-in function returns the data type of a variable or value in Python?', 'The built-in `type()` function inspects and returns the data type of any literal or variable in Python.', 'https://github.com/openstax/osbooks-introduction-python-programming/tree/2825b114221917bea5ae328a94e484b4da8a93ca')
on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, reference_url = excluded.reference_url;
update public.quiz_answers set is_correct = false where question_id in (select id from public.quiz_questions where quiz_id = md5('course-quiz:python-for-everyone:1')::uuid);
