  (md5('course-answer:python-for-everyone:1:4:1')::uuid, md5('course-question:python-for-everyone:1:4')::uuid, 1, 'The terminal permanently locks until a system reboot is completed.', false),
  (md5('course-answer:python-for-everyone:1:4:2')::uuid, md5('course-question:python-for-everyone:1:4')::uuid, 2, 'A missing executable error is raised and the terminal session terminates.', false),
  (md5('course-answer:python-for-everyone:1:4:3')::uuid, md5('course-question:python-for-everyone:1:4')::uuid, 3, 'Windows falls back to running a built-in Unix emulation layer.', false),
  (md5('course-answer:python-for-everyone:1:4:4')::uuid, md5('course-question:python-for-everyone:1:4')::uuid, 4, 'The current latest release of Python is installed automatically.', true),
  (md5('course-answer:python-for-everyone:1:5:1')::uuid, md5('course-question:python-for-everyone:1:5')::uuid, 1, '`py search --web`', false),
  (md5('course-answer:python-for-everyone:1:5:2')::uuid, md5('course-question:python-for-everyone:1:5')::uuid, 2, '`py list --online`', true),
  (md5('course-answer:python-for-everyone:1:5:3')::uuid, md5('course-question:python-for-everyone:1:5')::uuid, 3, '`python fetch --all`', false),
  (md5('course-answer:python-for-everyone:1:5:4')::uuid, md5('course-question:python-for-everyone:1:5')::uuid, 4, '`pymanager show --remote`', false),
  (md5('course-answer:python-for-everyone:1:6:1')::uuid, md5('course-question:python-for-everyone:1:6')::uuid, 1, 'To download and install SSL root certificates for Python''s use', true),
  (md5('course-answer:python-for-everyone:1:6:2')::uuid, md5('course-question:python-for-everyone:1:6')::uuid, 2, 'To register the application with Apple Developer Gatekeeper', false),
