  (md5('course-answer:python-for-everyone:1:8:4')::uuid, md5('course-question:python-for-everyone:1:8')::uuid, 4, '>>>', true),
  (md5('course-answer:python-for-everyone:1:9:1')::uuid, md5('course-question:python-for-everyone:1:9')::uuid, 1, 'By passing the command after the `-c` option, such as `python -c command`', true),
  (md5('course-answer:python-for-everyone:1:9:2')::uuid, md5('course-question:python-for-everyone:1:9')::uuid, 2, 'By prefixing the statement with an exclamation mark, like `python !command`', false),
