-- Quiz python-for-everyone/2: Making decisions quiz (15 questions)
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('course-quiz:python-for-everyone:2')::uuid, md5('chapter:python-for-everyone:2')::uuid, 'Making decisions quiz', 1, false)
on conflict (id) do update set title = excluded.title, is_preview = excluded.is_preview;
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('course-question:python-for-everyone:2:1')::uuid, md5('course-quiz:python-for-everyone:2')::uuid, 1, 'In Python, what does the keyword `elif` stand for?', 'In Python, the keyword `elif` is short for ''else if'' and is used to avoid excessive indentation when testing multiple conditions.', 'https://docs.python.org/3.15/tutorial/controlflow.html'),
  (md5('course-question:python-for-everyone:2:2')::uuid, md5('course-quiz:python-for-everyone:2')::uuid, 2, 'When does the `else` block of an `if ... elif ... else` construct execute?', 'The optional `else` clause serves as a fallback that executes only when the leading `if` and all subsequent `elif` conditions have evaluated to false.', 'https://docs.python.org/3.15/tutorial/controlflow.html'),
  (md5('course-question:python-for-everyone:2:3')::uuid, md5('course-quiz:python-for-everyone:2')::uuid, 3, 'How does Python determine which statements belong to an `if` block?', 'Python has no braces or end keyword for blocks: the statements indented under `if ...:` form its body, and the block ends where the indentation does.', 'https://docs.python.org/3.15/tutorial/controlflow.html'),
  (md5('course-question:python-for-everyone:2:4')::uuid, md5('course-quiz:python-for-everyone:2')::uuid, 4, 'How does Python evaluate a chain of `if ... elif ... elif ... else` statements?', 'Python tests conditions sequentially from top to bottom. As soon as one condition evaluates to true, that branch runs, and the remaining checks are skipped.', 'https://docs.python.org/3.15/tutorial/controlflow.html'),
  (md5('course-question:python-for-everyone:2:5')::uuid, md5('course-quiz:python-for-everyone:2')::uuid, 5, 'What numbers are generated by calling `range(5)`?', 'The built-in `range()` function generates an arithmetic progression where the specified end point is never part of the generated sequence.', 'https://docs.python.org/3.15/tutorial/controlflow.html'),
  (md5('course-question:python-for-everyone:2:6')::uuid, md5('course-quiz:python-for-everyone:2')::uuid, 6, 'What is the result of evaluating `list(range(0, 10, 3))` in Python?', 'Calling `range(0, 10, 3)` starts at 0 and increments by a step of 3 up to, but excluding, 10, producing 0, 3, 6, and 9.', 'https://docs.python.org/3.15/tutorial/controlflow.html'),
  (md5('course-question:python-for-everyone:2:7')::uuid, md5('course-quiz:python-for-everyone:2')::uuid, 7, 'Inside a loop, what is the effect of executing a `continue` statement?', 'The `continue` statement continues with the next iteration of the loop, skipping any remaining statements in the current iteration.', 'https://docs.python.org/3.15/tutorial/controlflow.html'),
  (md5('course-question:python-for-everyone:2:8')::uuid, md5('course-quiz:python-for-everyone:2')::uuid, 8, 'In Python, when does an `else` clause attached to a `for` loop execute?', 'A loop''s `else` clause executes after the loop completes its final iteration, but is skipped if the loop terminates early via a `break` statement.', 'https://docs.python.org/3.15/tutorial/controlflow.html'),
  (md5('course-question:python-for-everyone:2:9')::uuid, md5('course-quiz:python-for-everyone:2')::uuid, 9, 'What does a Python `for` statement iterate over?', 'Python''s `for` statement iterates over the items of any sequence, such as a list or a string, in the order that they appear.', 'https://docs.python.org/3.15/tutorial/controlflow.html'),
  (md5('course-question:python-for-everyone:2:10')::uuid, md5('course-quiz:python-for-everyone:2')::uuid, 10, 'What does the list method `append(value)` do?', 'The `append()` method adds the specified element to the end of the list, modifying the list in place.', 'https://github.com/openstax/osbooks-introduction-python-programming/tree/2825b114221917bea5ae328a94e484b4da8a93ca'),
  (md5('course-question:python-for-everyone:2:11')::uuid, md5('course-quiz:python-for-everyone:2')::uuid, 11, 'What happens when calling `fruits.remove("mango")` if `"mango"` is not in `fruits`?', 'The `remove()` method removes the first item equal to the specified value and raises a `ValueError` if no such item exists.', 'https://docs.python.org/3.15/tutorial/datastructures.html'),
  (md5('course-question:python-for-everyone:2:12')::uuid, md5('course-quiz:python-for-everyone:2')::uuid, 12, 'What does calling `my_list.pop()` without arguments do?', 'When no index is specified, `pop()` removes and returns the last item in the list.', 'https://docs.python.org/3.15/tutorial/datastructures.html'),
  (md5('course-question:python-for-everyone:2:13')::uuid, md5('course-quiz:python-for-everyone:2')::uuid, 13, 'What is the key difference between accessing a dictionary using `d[key]` and using `d.get(key)`?', 'Subscripting `d[key]` raises a `KeyError` if the key does not exist, whereas `d.get(key)` safely returns `None` or an optional fallback value.', 'https://github.com/openstax/osbooks-introduction-python-programming/tree/2825b114221917bea5ae328a94e484b4da8a93ca'),
  (md5('course-question:python-for-everyone:2:14')::uuid, md5('course-quiz:python-for-everyone:2')::uuid, 14, 'Which method allows you to loop through a dictionary and retrieve both keys and values at the same time?', 'Calling `items()` on a dictionary yields key-value pairs, allowing a `for` loop to unpack both the key and the corresponding value simultaneously.', 'https://github.com/openstax/osbooks-introduction-python-programming/tree/2825b114221917bea5ae328a94e484b4da8a93ca'),
  (md5('course-question:python-for-everyone:2:15')::uuid, md5('course-quiz:python-for-everyone:2')::uuid, 15, 'What is a fundamental rule regarding keys in a Python dictionary?', 'Each key in a dictionary must be unique, and keys must be immutable, such as strings or numbers. Values can repeat freely across different keys.', 'https://github.com/openstax/osbooks-introduction-python-programming/tree/2825b114221917bea5ae328a94e484b4da8a93ca')
on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, reference_url = excluded.reference_url;
update public.quiz_answers set is_correct = false where question_id in (select id from public.quiz_questions where quiz_id = md5('course-quiz:python-for-everyone:2')::uuid);
