  (md5('course-answer:python-for-everyone:2:3:2')::uuid, md5('course-question:python-for-everyone:2:3')::uuid, 2, 'By enclosing the statements within curly brackets `{}`', false),
  (md5('course-answer:python-for-everyone:2:3:3')::uuid, md5('course-question:python-for-everyone:2:3')::uuid, 3, 'By using an explicit `endif` keyword at the end of the block', false),
  (md5('course-answer:python-for-everyone:2:3:4')::uuid, md5('course-question:python-for-everyone:2:3')::uuid, 4, 'By placing all conditional statements on a single line', false),
  (md5('course-answer:python-for-everyone:2:4:1')::uuid, md5('course-question:python-for-everyone:2:4')::uuid, 1, 'It evaluates every branch and executes whichever branch is indented most', false),
  (md5('course-answer:python-for-everyone:2:4:2')::uuid, md5('course-question:python-for-everyone:2:4')::uuid, 2, 'It evaluates all branches simultaneously and runs the last matching condition', false),
  (md5('course-answer:python-for-everyone:2:4:3')::uuid, md5('course-question:python-for-everyone:2:4')::uuid, 3, 'It evaluates conditions in reverse order, starting from `else` and moving upwards', false),
  (md5('course-answer:python-for-everyone:2:4:4')::uuid, md5('course-question:python-for-everyone:2:4')::uuid, 4, 'It evaluates conditions from top to bottom, stopping after the first condition that is true', true),
  (md5('course-answer:python-for-everyone:2:5:1')::uuid, md5('course-question:python-for-everyone:2:5')::uuid, 1, 'The numbers 1, 2, 3, 4, and 5', false),
