-- Quiz python-for-everyone/3: Functions and files quiz (15 questions)
insert into public.quizzes (id, chapter_id, title, position, is_preview) values
  (md5('course-quiz:python-for-everyone:3')::uuid, md5('chapter:python-for-everyone:3')::uuid, 'Functions and files quiz', 1, false)
on conflict (id) do update set title = excluded.title, is_preview = excluded.is_preview;
insert into public.quiz_questions (id, quiz_id, position, prompt, explanation, reference_url) values
  (md5('course-question:python-for-everyone:3:1')::uuid, md5('course-quiz:python-for-everyone:3')::uuid, 1, 'Which keyword is used in Python to introduce a new function definition?', 'In Python, a function definition is introduced using the `def` keyword, followed by the function name, parentheses for any parameters, and a colon.', 'https://github.com/openstax/osbooks-introduction-python-programming/tree/2825b114221917bea5ae328a94e484b4da8a93ca'),
  (md5('course-question:python-for-everyone:3:2')::uuid, md5('course-quiz:python-for-everyone:3')::uuid, 2, 'What value is returned by a Python function that finishes executing without reaching an explicit `return` statement?', 'Functions that do not execute a `return` statement, or that execute a `return` without an expression, return the built-in value `None`.', 'https://docs.python.org/3.15/tutorial/controlflow.html'),
  (md5('course-question:python-for-everyone:3:3')::uuid, md5('course-quiz:python-for-everyone:3')::uuid, 3, 'When does Python evaluate default parameter values for a function?', 'Default argument values are evaluated only once, at the point of function definition in the defining scope.', 'https://docs.python.org/3.15/tutorial/controlflow.html'),
  (md5('course-question:python-for-everyone:3:4')::uuid, md5('course-quiz:python-for-everyone:3')::uuid, 4, 'What happens to a local variable created inside a function once that function finishes executing?', 'A variable created within a function has local scope and only exists while that function runs. Once execution finishes, local variables no longer exist.', 'https://github.com/openstax/osbooks-introduction-python-programming/tree/2825b114221917bea5ae328a94e484b4da8a93ca'),
  (md5('course-question:python-for-everyone:3:5')::uuid, md5('course-quiz:python-for-everyone:3')::uuid, 5, 'Which rule must be followed when combining positional and keyword arguments in a function call?', 'When mixing positional and keyword arguments in a function call, positional arguments must always come first, before any keyword arguments.', 'https://github.com/openstax/osbooks-introduction-python-programming/tree/2825b114221917bea5ae328a94e484b4da8a93ca'),
  (md5('course-question:python-for-everyone:3:6')::uuid, md5('course-quiz:python-for-everyone:3')::uuid, 6, 'Where should a docstring be placed within a function definition?', 'A docstring is an optional string literal placed as the very first statement of the function body, used to describe what the function does.', 'https://docs.python.org/3.15/tutorial/controlflow.html'),
  (md5('course-question:python-for-everyone:3:7')::uuid, md5('course-quiz:python-for-everyone:3')::uuid, 7, 'If you call `open("data.txt")` without specifying a mode parameter, which mode does Python use by default?', 'The default mode of the `open()` function is read mode (`''r''`), which opens an existing file for reading only.', 'https://github.com/openstax/osbooks-introduction-python-programming/tree/2825b114221917bea5ae328a94e484b4da8a93ca'),
  (md5('course-question:python-for-everyone:3:8')::uuid, md5('course-quiz:python-for-everyone:3')::uuid, 8, 'What occurs if you open an existing file using `''w''` mode instead of `''a''` mode?', 'In `''w''` (write) mode, if the file already exists, its contents are overwritten and erased. In `''a''` (append) mode, data is added to the end.', 'https://github.com/openstax/osbooks-introduction-python-programming/tree/2825b114221917bea5ae328a94e484b4da8a93ca'),
  (md5('course-question:python-for-everyone:3:9')::uuid, md5('course-quiz:python-for-everyone:3')::uuid, 9, 'What is the primary advantage of using a `with` statement when opening a file?', 'The `with` statement ensures the file is properly closed once its suite finishes, even if an exception occurs during execution.', 'https://docs.python.org/3.15/tutorial/inputoutput.html'),
  (md5('course-question:python-for-everyone:3:10')::uuid, md5('course-quiz:python-for-everyone:3')::uuid, 10, 'What does the `readline()` method return when it reaches the end of a file?', 'When `readline()` reaches the end of the file, it returns an empty string `""`. A blank line in the file returns `"\n"` instead.', 'https://docs.python.org/3.15/tutorial/inputoutput.html'),
  (md5('course-question:python-for-everyone:3:11')::uuid, md5('course-quiz:python-for-everyone:3')::uuid, 11, 'What type of argument does the `write()` method of a text file object accept?', 'The `write()` method only accepts strings. Other data types must be converted (for example, using `str()`) before writing.', 'https://github.com/openstax/osbooks-introduction-python-programming/tree/2825b114221917bea5ae328a94e484b4da8a93ca'),
  (md5('course-question:python-for-everyone:3:12')::uuid, md5('course-quiz:python-for-everyone:3')::uuid, 12, 'Why is looping directly over a file object using `for line in f:` recommended for reading lines?', 'Looping directly over the file object is memory efficient, fast, and simple because Python loads lines on demand rather than storing the whole file at once.', 'https://docs.python.org/3.15/tutorial/inputoutput.html'),
  (md5('course-question:python-for-everyone:3:13')::uuid, md5('course-quiz:python-for-everyone:3')::uuid, 13, 'In a journal application, why pass `end=""` to `print()` when printing lines read directly from a file?', 'Lines read from a text file retain their trailing `\n`. Because `print()` adds a newline by default, specifying `end=""` avoids printing duplicate empty lines.', 'https://docs.python.org/3.15/tutorial/inputoutput.html'),
  (md5('course-question:python-for-everyone:3:14')::uuid, md5('course-quiz:python-for-everyone:3')::uuid, 14, 'Which mode should you specify in `open()` so that new entries are added to the end of an existing file without deleting past records?', 'Append mode (`''a''`) opens a file to add new data to the end without deleting or overwriting the existing content.', 'https://github.com/openstax/osbooks-introduction-python-programming/tree/2825b114221917bea5ae328a94e484b4da8a93ca'),
  (md5('course-question:python-for-everyone:3:15')::uuid, md5('course-quiz:python-for-everyone:3')::uuid, 15, 'What happens if a program attempts to call `read()` or `write()` on a file object after it has been closed?', 'After a file object is closed (either by `close()` or exiting a `with` block), attempts to use it will fail and raise a `ValueError`.', 'https://docs.python.org/3.15/tutorial/inputoutput.html')
on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, reference_url = excluded.reference_url;
update public.quiz_answers set is_correct = false where question_id in (select id from public.quiz_questions where quiz_id = md5('course-quiz:python-for-everyone:3')::uuid);
